package com.nexus.web; import com.nexus.service.Accounts; import com.nexus.domain.*; import com.nexus.domain.Rules.Role; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.*; import org.springframework.security.web.context.SecurityContextRepository; import org.springframework.security.web.csrf.CsrfToken; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final Accounts accounts;private final SecurityContextRepository contexts;public AuthController(Accounts a,SecurityContextRepository c){accounts=a;contexts=c;}
 public record Login(@NotBlank @Email @Size(max=150) String email,@NotBlank @Size(max=72) String password){} public record Register(@NotBlank @Size(max=100) String name,@NotBlank @Email @Size(max=150) String email,@NotBlank @Size(min=10,max=72) String password){}
 @GetMapping("/csrf") public Map<String,String> csrf(CsrfToken token){return Map.of("token",token.getToken(),"header",token.getHeaderName());}
 @PostMapping("/register") public Map<String,Object> register(@Valid @RequestBody Register r){return Views.user(accounts.register(r.name(),r.email(),r.password(),Role.EMPLOYEE));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody Login r,HttpServletRequest request,HttpServletResponse response){var found=accounts.repo.findByEmail(accounts.normalize(r.email()));if(found.isEmpty()||!accounts.matches(r.password(),found.get()))return ResponseEntity.status(401).body(Map.of("message","Invalid credentials"));Account a=found.get();request.getSession(true);request.changeSessionId();var auth=new UsernamePasswordAuthenticationToken(a.email,null,List.of(new SimpleGrantedAuthority("ROLE_"+a.role())));var ctx=SecurityContextHolder.createEmptyContext();ctx.setAuthentication(auth);SecurityContextHolder.setContext(ctx);contexts.saveContext(ctx,request,response);return ResponseEntity.ok(Views.user(a));}
 @GetMapping("/me") public Map<String,Object> me(Principal p){return Views.user(accounts.current(p.getName()));}
}
